"use client";

import {
  barLabelInterval,
  barsOf,
  isSignature,
  type SignatureChange,
  secondsPerBar,
  type Tempo,
} from "@audio-ui/core/time";
import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";
import { TimelineMark } from "@/components/audio-ui/timeline";

/** A named point of the arrangement, in its time. */
export interface Locator {
  at: number;
  name: string;
}

/** A time-signature change, with an id that stays the same as it moves, so its button keeps the focus. */
export type Signature = SignatureChange & { id: string };

/** "7/8" as a signature, or null when it is not one a bar can have. */
export function parseSignature(text: string) {
  const [beats, unit] = text.split("/").map((part) => Number(part.trim()));
  return beats !== undefined && unit !== undefined && isSignature(beats, unit)
    ? { beatUnit: unit, beatsPerBar: beats }
    : null;
}

/** Keeps a press inside a field from reaching the lane under it. */
function stopPress(event: PointerEvent<HTMLElement>) {
  event.stopPropagation();
}

/** A mark for a marker: no tick or padding of a mark's own, so the marker's own line stands on its time. */
const ON_ITS_TIME = "border-s-0 ps-0";

/**
 * A locator, on its time on a lane: press it to put the cursor there,
 * double-click it or press Enter to rename it (Enter keeps the name, Escape
 * drops the change), Delete takes it away.
 */
function TimelineLocator({
  locator,
  onJump,
  onRemove,
  onRename,
}: {
  locator: Locator;
  onJump: (at: number) => void;
  onRemove: (at: number) => void;
  onRename: (at: number, name: string) => void;
}) {
  const { at, name } = locator;
  const [editing, setEditing] = useState(false);
  const handleClick = useCallback(() => onJump(at), [at, onJump]);
  const startEditing = useCallback(() => setEditing(true), []);
  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Delete" || event.key === "Backspace") {
        event.preventDefault();
        event.stopPropagation();
        onRemove(at);
      } else if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        setEditing(true);
      }
    },
    [at, onRemove]
  );
  const handleEditKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      event.stopPropagation();
      if (event.key === "Enter") {
        const next = event.currentTarget.value.trim();
        if (next) {
          onRename(at, next);
        }
        setEditing(false);
      } else if (event.key === "Escape") {
        setEditing(false);
      }
    },
    [at, onRename]
  );
  const handleBlur = useCallback(() => setEditing(false), []);
  const handleRemove = useCallback(() => onRemove(at), [at, onRemove]);
  // The menu hands focus back as it closes, which would end the edit: open the field after it.
  const renameLater = useRef(false);
  const renameWhenClosed = useCallback(() => {
    renameLater.current = true;
  }, []);
  const handleMenuClosed = useCallback((open: boolean) => {
    if (!open && renameLater.current) {
      renameLater.current = false;
      setEditing(true);
    }
  }, []);

  if (editing) {
    return (
      <TimelineMark className={ON_ITS_TIME} value={at}>
        <input
          aria-label="Locator name"
          autoFocus
          className="h-full w-24 border-primary border-s-2 bg-background px-1 text-primary text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring"
          data-slot="timeline-locator-input"
          defaultValue={name}
          onBlur={handleBlur}
          onKeyDown={handleEditKeyDown}
          onPointerDown={stopPress}
        />
      </TimelineMark>
    );
  }
  return (
    <TimelineMark className={ON_ITS_TIME} value={at}>
      <ContextMenu onOpenChangeComplete={handleMenuClosed}>
        <ContextMenuTrigger
          render={
            <button
              aria-label={`Locator ${name}`}
              className="pointer-events-auto flex h-full items-center whitespace-nowrap border-primary border-s-2 ps-1 pe-2 text-primary text-xs outline-none hover:bg-primary/10 focus-visible:ring-2 focus-visible:ring-ring"
              data-slot="timeline-locator"
              onClick={handleClick}
              onDoubleClick={startEditing}
              onKeyDown={handleKeyDown}
              type="button"
            />
          }
        >
          {name}
        </ContextMenuTrigger>
        <ContextMenuContent className="w-auto min-w-32">
          <ContextMenuItem onClick={renameWhenClosed}>Rename</ContextMenuItem>
          <ContextMenuSeparator />
          <ContextMenuItem onClick={handleRemove} variant="destructive">
            Delete
          </ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>
    </TimelineMark>
  );
}

/**
 * A time-signature change, on its time on a lane: press it to put the
 * cursor there, double-click it or press Enter to type a new signature such
 * as 7/8 (Enter keeps it, Escape drops it), Left and Right move it by `step`,
 * Delete takes it away. Which change is being typed is held by the host
 * (`editing`), so a change just added can open ready to type.
 */
function TimelineSignature({
  change,
  editing,
  onEditingChange,
  onJump,
  onMove,
  onRemove,
  onSet,
  step,
}: {
  change: Signature;
  editing: boolean;
  onEditingChange: (id: string | null) => void;
  onJump: (at: number) => void;
  onMove: (id: string, to: number) => void;
  onRemove: (id: string) => void;
  onSet: (id: string, beatsPerBar: number, beatUnit: number) => void;
  step: number;
}) {
  const { at, beatUnit, beatsPerBar, id } = change;
  const label = `${beatsPerBar}/${beatUnit}`;
  const handleClick = useCallback(() => onJump(at), [at, onJump]);
  const startEditing = useCallback(
    () => onEditingChange(id),
    [id, onEditingChange]
  );
  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>) => {
      const direction = { ArrowLeft: -1, ArrowRight: 1 }[event.key];
      if (event.key === "Delete" || event.key === "Backspace") {
        onRemove(id);
      } else if (event.key === "Enter") {
        onEditingChange(id);
      } else if (direction && step > 0) {
        onMove(id, at + direction * step);
      } else {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
    },
    [at, id, onEditingChange, onMove, onRemove, step]
  );
  const handleEditKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      event.stopPropagation();
      if (event.key === "Enter") {
        const parsed = parseSignature(event.currentTarget.value);
        if (parsed) {
          onSet(id, parsed.beatsPerBar, parsed.beatUnit);
        }
        onEditingChange(null);
      } else if (event.key === "Escape") {
        onEditingChange(null);
      }
    },
    [id, onEditingChange, onSet]
  );
  const stopEditing = useCallback(
    () => onEditingChange(null),
    [onEditingChange]
  );
  const handleRemove = useCallback(() => onRemove(id), [id, onRemove]);

  if (editing) {
    return (
      <TimelineMark className={ON_ITS_TIME} value={at}>
        <input
          aria-label="Time signature, such as 7/8"
          autoFocus
          className="h-full w-14 border-primary border-s-2 bg-background px-1 text-primary text-xs tabular-nums outline-none focus-visible:ring-2 focus-visible:ring-ring"
          data-slot="timeline-signature-input"
          defaultValue={label}
          onBlur={stopEditing}
          onKeyDown={handleEditKeyDown}
          onPointerDown={stopPress}
        />
      </TimelineMark>
    );
  }
  return (
    <TimelineMark className={ON_ITS_TIME} value={at}>
      <ContextMenu>
        <ContextMenuTrigger
          render={
            <button
              aria-label={`Time signature ${label}`}
              className="pointer-events-auto flex h-full items-center whitespace-nowrap border-foreground/60 border-s-2 ps-1 pe-2 text-xs tabular-nums outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring"
              data-slot="timeline-signature"
              onClick={handleClick}
              onDoubleClick={startEditing}
              onKeyDown={handleKeyDown}
              type="button"
            />
          }
        >
          {label}
        </ContextMenuTrigger>
        <ContextMenuContent className="w-auto min-w-32">
          <ContextMenuItem onClick={startEditing}>Edit</ContextMenuItem>
          <ContextMenuSeparator />
          <ContextMenuItem onClick={handleRemove} variant="destructive">
            Delete
          </ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>
    </TimelineMark>
  );
}

/**
 * The bars of a ruler, through the time-signature changes: their numbers, every
 * few bars so they never crowd at this zoom, and the bars a change cuts short,
 * hatched. Put it inside a `TimelineRuler`.
 */
function TimelineBarMarks({
  duration,
  signatures,
  tempo,
  zoom,
}: {
  /** The arrangement's length, in seconds. */
  duration: number;
  signatures: readonly SignatureChange[];
  tempo: Tempo;
  /** The timeline's zoom, in px per second. */
  zoom: number;
}) {
  const bars = useMemo(
    () => barsOf(tempo, signatures, duration),
    [duration, signatures, tempo]
  );
  // Whole bars, counted rather than divided, so no tempo leaves a label like 6.9999.
  const every = Math.max(
    1,
    Math.round(barLabelInterval(zoom, tempo) / secondsPerBar(tempo))
  );
  return (
    <>
      {bars
        .filter((item) => item.partial)
        .map((item) => (
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-y-0 bg-[repeating-linear-gradient(135deg,var(--muted-foreground)_0_1px,transparent_1px_6px)] opacity-30"
            data-slot="timeline-partial-bar"
            key={item.start}
            style={{
              left: `calc(var(--timeline-unit) * ${item.start})`,
              width: `calc(var(--timeline-unit) * ${item.length})`,
            }}
          />
        ))}
      {bars
        .filter((_, index) => index % every === 0)
        .map((item) => (
          <TimelineMark key={item.start} value={item.start}>
            {item.number}
          </TimelineMark>
        ))}
    </>
  );
}

export { TimelineBarMarks, TimelineLocator, TimelineSignature };

"use client";

import { useCallback, useMemo, useState } from "react";
import type {
  ArrangementCommand,
  ArrangementState,
} from "@/lib/arrangement-state";

export interface UseTimelineMarkersOptions {
  /** The arrangement's commands, from `useArrangement`. */
  dispatch: (command: ArrangementCommand) => ArrangementState;
  /** Where the cursor is, in seconds: where a new locator or time signature goes. */
  getPosition: () => number;
  /** A locator or a time signature was pressed: put the cursor there. */
  onJump: (at: number) => void;
  /** How far the arrows move a time signature: the grid, in seconds. */
  step: number;
}

/**
 * The commands behind `TimelineLocator` and `TimelineSignature`: spread
 * `locator` on the one and `signature` on the other, with `editing` set for
 * the change `editingSignature` names. `addLocator` puts a locator at the
 * cursor; `addSignature` puts a change there, in the signature already in
 * force, and opens it to be typed.
 */
export function useTimelineMarkers({
  dispatch,
  getPosition,
  onJump,
  step,
}: UseTimelineMarkersOptions) {
  const [editingSignature, setEditingSignature] = useState<string | null>(null);
  const addLocator = useCallback(
    () => dispatch({ at: getPosition(), type: "add-locator" }),
    [dispatch, getPosition]
  );
  const addSignature = useCallback(() => {
    const at = getPosition();
    const next = dispatch({ at, type: "add-signature" });
    const added = next.doc.signatures.find((change) => change.at === at);
    if (added) {
      setEditingSignature(added.id);
    }
  }, [dispatch, getPosition]);
  const locator = useMemo(
    () => ({
      onJump,
      onRemove: (at: number) => dispatch({ at, type: "remove-locator" }),
      onRename: (at: number, name: string) =>
        dispatch({ at, name, type: "rename-locator" }),
    }),
    [dispatch, onJump]
  );
  const signature = useMemo(
    () => ({
      onEditingChange: setEditingSignature,
      onJump,
      onMove: (id: string, to: number) =>
        dispatch({ id, to, type: "move-signature" }),
      onRemove: (id: string) => dispatch({ id, type: "remove-signature" }),
      onSet: (id: string, beatsPerBar: number, beatUnit: number) =>
        dispatch({ beatsPerBar, beatUnit, id, type: "set-signature" }),
      step,
    }),
    [dispatch, onJump, step]
  );
  return { addLocator, addSignature, editingSignature, locator, signature };
}
